// Concentric rings pulsing outward.
// Pulse phase uses iGlobalTime (comp clock) so it stays in sync wherever the layer starts.
// Fade-in uses iTime (layer-local) so it begins when the layer begins.
uniform float uSpeed;     // @param 0.5 0 3
uniform float uDensity;   // @param 8.0 1 30
uniform float uWidth;     // @param 0.18 0.02 0.5
uniform float uFadeIn;    // @param 1.0 0 5
uniform vec3  uRingColor; // @param #FF6B1A
uniform vec3  uBgColor;   // @param #08080B

void main() {
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float r = length(p);

  // Comp-synced phase: rings travel outward
  float phase = r * uDensity - iGlobalTime * uSpeed * uDensity * 0.25;
  float f = fract(phase);
  float d = min(f, 1.0 - f);                       // distance to ring center (0..0.5)
  float aa = fwidth(phase) * 1.5;
  float ring = 1.0 - smoothstep(uWidth * 0.5 - aa, uWidth * 0.5 + aa, d);
  float glow = exp(-d * 14.0) * 0.35;

  // Rings soften toward the edge
  float falloff = 1.0 - smoothstep(0.15, 0.85, r);

  // Layer-local fade-in
  float fade = uFadeIn > 0.0 ? smoothstep(0.0, 1.0, clamp(iTime / uFadeIn, 0.0, 1.0)) : 1.0;

  float k = (ring + glow) * falloff * fade;
  vec3 col = mix(uBgColor, uRingColor, clamp(k, 0.0, 1.0));
  col += uRingColor * pow(ring * falloff, 4.0) * 0.25 * fade;
  fragColor = vec4(col, 1.0);
}
